// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        vm.assume(actor.code.length == 0);
        amount = bound(amount, 1, 1 ether);

        // deploy a functional log and register it BEFORE initialization
        AddMsgLog log = new AddMsgLog();
        c.SetLogFile(address(log));
        c.Deposit{value: 1}();
        c.Initialized();

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Deposit{value: amount}() { ok = true; } catch { ok = false; }

        // Rule: with a working Log registered, any account's Deposit succeeds.
        assertTrue(ok);
    }
}

contract AddMsgLog {
    event M(address Sender, uint Val, string Data);
    function AddMessage(address _adr, uint _val, string memory _data) public {
        emit M(_adr, _val, _data);
    }
}
